import type { DynamicModule, Type } from '@nestjs/common';
import {
  callAppShutdownHook,
  callBeforeAppShutdownHook,
  callModuleBootstrapHook,
  callModuleDestroyHook,
  callModuleInitHook,
} from '../../hooks/index.js';
import { ModuleOverride } from '../../interfaces/module-override.interface.js';
import { DependenciesScanner } from '../../scanner.js';
import { ModuleCompiler } from '../compiler.js';
import { SilentLogger } from '../helpers/silent-logger.js';
import { InstanceLoader } from '../instance-loader.js';
import { Module } from '../module.js';
import { ModuleRef } from '../module-ref.js';
import { ModulesContainer } from '../modules-container.js';
import { LazyModuleLoaderLoadOptions } from './lazy-module-loader-options.interface.js';

/**
 * Tracks the lifecycle hook state of a single lazily loaded module instance.
 */
interface LazyModuleHookRecord {
  module: Module;
  onModuleInit: boolean;
  onApplicationBootstrap: boolean;
}

export class LazyModuleLoader {
  /**
   * In-flight loads keyed by module identity (the module class).
   */
  private readonly inFlightLoads = new Map<Type<unknown>, Promise<ModuleRef>>();
  /**
   * Resolved module references keyed by module identity (the module class).
   * Dynamic metadata does not take part in the identity.
   */
  private readonly moduleRefsByType = new Map<Type<unknown>, ModuleRef>();
  private readonly targetModulesByType = new Map<Type<unknown>, Module>();
  /**
   * Hook records of all lazily loaded modules, in startup order.
   */
  private readonly hookRecords: LazyModuleHookRecord[] = [];
  private readonly hookRecordsByType = new Map<Type<unknown>, LazyModuleHookRecord[]>();
  private readonly registeredModules = new Set<Module>();
  private startupHooksChain: Promise<void> = Promise.resolve();
  private closePromise: Promise<void> | null = null;

  constructor(...same...) {}

  public async load(loaderFn, loadOpts?): Promise<ModuleRef> {
    if (this.closePromise) {
      throw new Error('Application is closed');
    }
    const moduleClassOrDynamicDefinition = await loaderFn();
    const { type } = this.moduleCompiler.extractMetadata(moduleClassOrDynamicDefinition);

    const inFlight = this.inFlightLoads.get(type);
    if (inFlight) {
      return inFlight;
    }
    const cachedModuleRef = this.moduleRefsByType.get(type);
    if (cachedModuleRef) {
      return cachedModuleRef;
    }
    const loadPromise = this.doLoad(moduleClassOrDynamicDefinition, type, loadOpts);
    this.inFlightLoads.set(type, loadPromise);
    try {
      return await loadPromise;
    } finally {
      this.inFlightLoads.delete(type);
    }
  }

  public async close(): Promise<void> {
    if (!this.closePromise) {
      this.closePromise = this.executeClose();
    }
    return this.closePromise;
  }

  private async doLoad(def, type, loadOpts): Promise<ModuleRef> {
    const originalLogger = (this.instanceLoader as any).logger;
    try {
      this.registerLoggerConfiguration(loadOpts);
      const moduleInstances = await this.dependenciesScanner.scanForModules({
        moduleDefinition: def,
        overrides: this.moduleOverrides,
        lazy: true,
      });
      if (moduleInstances.length === 0) {
        // The module has been loaded already. Complete any pending
        // lifecycle hooks (e.g. a previous load failed midway) and
        // retrieve a module reference from the existing container.
        await this.scheduleStartupHooks(this.hookRecordsByType.get(type) ?? []);
        const { token } = await this.moduleCompiler.compile(def);
        const moduleInstance = this.modulesContainer.get(token) ?? this.targetModulesByType.get(type);
        const moduleRef = moduleInstance && this.getTargetModuleRef(moduleInstance);
        if (moduleRef) {
          this.moduleRefsByType.set(type, moduleRef);
        }
        return moduleRef;
      }
      const lazyModulesContainer = this.createLazyModulesContainer(moduleInstances);
      await this.dependenciesScanner.scanModulesForDependencies(lazyModulesContainer);
      await this.instanceLoader.createInstancesOfDependencies(lazyModulesContainer);
      const [targetModule] = moduleInstances;
      this.targetModulesByType.set(type, targetModule);
      const records = this.registerHookRecords(type, moduleInstances);
      await this.scheduleStartupHooks(records);
      const moduleRef = this.getTargetModuleRef(targetModule);
      this.moduleRefsByType.set(type, moduleRef);
      return moduleRef;
    } finally {
      if (loadOpts?.logger === false) {
        this.instanceLoader.setLogger(originalLogger);
      }
    }
  }
  ...
}
