54	  /**
55	   * Serializes startup hook execution so concurrent loads cannot run
56	   * lifecycle hooks of the same module instance twice. Never rejects.
57	   */
58	  private startupHooksChain: Promise<void> = Promise.resolve();
59	  private closePromise: Promise<void> | null = null;
