65	    private readonly modulesContainer: ModulesContainer,
66	    private readonly moduleOverrides?: ModuleOverride[],
67	  ) {}
68	
69	  public async load(
70	    loaderFn: () =>
71	      Promise<Type<unknown> | DynamicModule> | Type<unknown> | DynamicModule,
72	    loadOpts?: LazyModuleLoaderLoadOptions,
73	  ): Promise<ModuleRef> {
74	    if (this.closePromise) {
75	      throw new Error('Application is closed');
76	    }
77	    const moduleClassOrDynamicDefinition = await loaderFn();
78	    const { type } = this.moduleCompiler.extractMetadata(
79	      moduleClassOrDynamicDefinition,
