81	
82	    const inFlightLoad = this.inFlightLoads.get(type);
83	    if (inFlightLoad) {
84	      return inFlightLoad;
85	    }
86	    const cachedModuleRef = this.moduleRefsByType.get(type);
87	    if (cachedModuleRef) {
88	      return cachedModuleRef;
89	    }
90	    const loadPromise = this.doLoad(
91	      moduleClassOrDynamicDefinition,
92	      type,
