100	    }
101	  }
102	
103	  /**
104	   * Runs the shutdown lifecycle hooks (`onModuleDestroy`,
105	   * `beforeApplicationShutdown`, `onApplicationShutdown`) on every lazily
106	   * loaded module, in reverse startup order. Each hook is called once per
107	   * instance; repeated or concurrent calls share the same execution.
108	   */
109	  public async close(): Promise<void> {
110	    if (!this.closePromise) {
111	      this.closePromise = this.executeClose();
112	    }
113	    return this.closePromise;
114	  }
