116	  private async doLoad(
117	    moduleClassOrDynamicDefinition: Type<unknown> | DynamicModule,
118	    type: Type<unknown>,
119	    loadOpts?: LazyModuleLoaderLoadOptions,
120	  ): Promise<ModuleRef> {
121	    const originalLogger = (this.instanceLoader as any).logger;
122	    try {
123	      this.registerLoggerConfiguration(loadOpts);
124	
125	      const moduleInstances = await this.dependenciesScanner.scanForModules({
126	        moduleDefinition: moduleClassOrDynamicDefinition,
127	        overrides: this.moduleOverrides,
128	        lazy: true,
129	      });
